def count_vowels(s: str) -> int:
    vowels = set("aeiouAEIOU")
    count = 0
    length = len(s)
    for i, char in enumerate(s):
        if i > 0 and s[i-1] in vowels:
            count += 1
        elif i < length - 1 and s[i+1] in vowels:
            count += 1
    return count
